import React, { useState } from "react";
import styles from "./AiSearch.module.css";

// 이미지 아이콘/캐릭터
import BusIcon from "../assets/Bus2.png";
import LightningIcon from "../assets/Lightning.png";
import QuestionLogo from "../assets/물음표로고 .png";
import ChatCircleDots from "../assets/ChatCircleDots.png";
import BlackCircle from "../assets/blackcircle.png";
import HealthIcon from "../assets/Health2.png";
import LightbulbIcon from "../assets/Lightbulb.png";
import History from "../assets/History.png";
import SearchBalloon from "../assets/searchBalloon.png";
import SparkleIcon from "../assets/sparkle.png";

// *** PNG로 교체된 아이콘들 ***
import PencilIcon from "../assets/Pencil.png";        // 연필
import CursorIcon from "../assets/Cursor.png";        // 커서
import ChainIcon from "../assets/chain.png";          // 체인(링크)
import HappyLogo from "../assets/HappyLogo.png";      // 캐릭터
import AnswerBubble from "../assets/Answer.png";      // 말풍선

const recentSearchPool = [
  ["문화혜택", "서산 맛집 추천", "복지 혜택 신청"],
  ["교통정보", "서산시 행사", "서산 카페"],
  ["서산 명소", "전통시장", "주말 이벤트"],
  ["공원 위치", "체육시설", "노인복지관"],
  ["가족 여행지", "아이와 갈만한 곳", "주차장 위치"]
];

function getRandomList(prevList) {
  const candidates = recentSearchPool.filter(
    arr => arr.join("|") !== prevList.join("|")
  );
  if (candidates.length === 0) return prevList;
  const i = Math.floor(Math.random() * candidates.length);
  return candidates[i];
}

export default function AiSearch() {
  const [inputValue, setInputValue] = useState("");
  const [recentSearches, setRecentSearches] = useState(recentSearchPool[0]);
  const [searchResult, setSearchResult] = useState(null);
  const [tab, setTab] = useState("answer"); // "answer" | "source"

  // 검색 시 호출
  const handleAiSearch = () => {
    if (!inputValue.trim()) return;

    setSearchResult({
      answer: (
        <>
          서산시의 노인 복지에 대한 주요 내용은 다음과 같아요.<br /><br />
          <b>• 주요 복지 정책 및 사업</b><br />
          <b>노인여가복지시설 지원:</b> 서산시는 경로당, 마을회관 등 관내 440개의 노인여가복지시설을 대상으로 냉난방비와 각종 물품을 지원하고 있습니다. 또한, 어르신들의 안전을 위해 시설에 대한 종합 보험 가입을 지원하고, 주기적인 소독을 실시하여 전염병을 예방하고 있습니다.<br />
          <b>노인 일자리 사업:</b> 어르신들의 경제적 안정과 사회 참여를 돕기 위해 노인 일자리를 제공하고 있습니다.<br /><br />
          <b>• 주요 복지 시설</b><br />
          <b>서산노인복지센터:</b> 지곡면에 위치한 시설로, 노인 장기요양보험 관련 서비스를 제공합니다.<br />
          <b>서산탑노인복지센터:</b> 음암면에 위치한 요양시설입니다.<br />
          <b>우리들주야간노인복지센터:</b> 수석동에 위치하며, 방문목욕, 방문요양, 주야간 보호 등 다양한 재가노인복지 서비스를 제공합니다.
        </>
      ),
      sources: [
        {
          title: "충청남도 서산시_재가노인 복지시설",
          link: "#",
          provider: "충청남도 데이터포털 올담",
        },
        {
          title: "충청남도 서산시_노인의료복지시설",
          link: "#",
          provider: "충청남도 데이터포털 올담",
        }
      ]
    });

    setTab("answer");
    setInputValue("");
  };

  // 최근 검색 새로고침
  const handleRefresh = () => {
    setRecentSearches(prevList => getRandomList(prevList));
  };

  return (
    <div className={styles.bg}>
      {/* 상단 검색바 + 배경 */}
      <div className={styles.topSection}>
        <div className={styles.bgBox}>
          <div className={styles.aiSearchBalloonBox}>
            <img src={SearchBalloon} alt="검색 말풍선" className={styles.balloonBg} />
            <div className={styles.balloonContent}>
              <input
                className={styles.balloonInput}
                placeholder="찾으시는 소식이 있나요?"
                value={inputValue}
                onChange={e => setInputValue(e.target.value)}
                onKeyDown={e => {
                  if (e.key === "Enter") handleAiSearch();
                }}
              />
              <span
                className={styles.aiSearchRight}
                onClick={handleAiSearch}
                tabIndex={0}
                style={{ cursor: "pointer" }}
                onKeyDown={e => { if (e.key === "Enter") handleAiSearch(); }}
              >
                <span className={styles.aiSearchBold}>AI 검색</span>
                <img src={SparkleIcon} alt="" className={styles.sparkleIcon} />
              </span>
            </div>
          </div>
          <div className={styles.buttonGroup}>
            <div className={styles.searchHistoryTitle}>
              <img
                src={History}
                alt="새로고침"
                className={styles.historyIcon}
                style={{ cursor: 'pointer', display: 'inline-flex', alignItems: 'center' }}
                onClick={handleRefresh}
                tabIndex={0}
                onKeyDown={e => {
                  if (e.key === "Enter" || e.key === " ") handleRefresh();
                }}
                aria-label="새로고침"
              />
              최근 검색
            </div>
            {recentSearches.map((item, idx) => (
              <button key={item + idx} className={styles.pillBtn}>{item}</button>
            ))}
          </div>
        </div>
        <img src={QuestionLogo} alt="logo" className={styles.questionLogo} draggable="false" />
      </div>

      {/* --- AI 검색 결과 영역 --- */}
      {searchResult && (
        <div className={styles.aiResultWrap}>
          <div className={styles.aiResultHeader}>
            <img src={HappyLogo} alt="캐릭터" className={styles.resultLogo} />
            <div className={styles.speechBubble}>
              <img src={AnswerBubble}/>
              <img src={SparkleIcon} alt="" style={{ width: 18, verticalAlign: 'middle', marginLeft: 4 }} />
            </div>
          </div>
          {/* 답변/출처 탭 */}
          <div className={styles.resultTabs}>
            <div
              className={`${styles.resultTab} ${tab === "answer" ? styles.active : ""}`}
              onClick={() => setTab("answer")}
            >
              답변
            </div>
            <div
              className={`${styles.resultTab} ${tab === "source" ? styles.active : ""}`}
              onClick={() => setTab("source")}
            >
              출처
            </div>
          </div>
          {/* 답변 내용 */}
          {tab === "answer" && (
            <div className={styles.resultMainCard}>
              <div className={styles.resultAnswerText}>
                {searchResult.answer}
              </div>
            </div>
          )}
          {/* 출처 내용 (여기 PNG 아이콘!) */}
          {tab === "source" && (
            <div className={styles.resultSourceSection}>
              <div className={styles.resultSourceGuide}>
                답변에 사용된 출처를 알려드릴게요.
              </div>
              <div className={styles.resultSourceList}>
                {searchResult.sources.map((item, idx) => (
                  <div className={styles.resultSourceCard} key={idx}>
                    <div className={styles.resultSourceNum}>{idx + 1}</div>
                    <div className={styles.resultSourceCardContent}>
                      <div className={styles.resultSourceTitleRow}>
                        <b className={styles.resultSourceTitle}>{item.title}</b>
                        <a
                          href={item.link}
                          target="_blank"
                          rel="noopener noreferrer"
                          className={styles.resultSourceLinkIcon}
                          aria-label="바로가기"
                        >
                          <img src={ChainIcon} alt="링크" style={{width:18, height:18, marginLeft:3, verticalAlign:'middle'}} />
                        </a>
                      </div>
                      <div className={styles.resultSourceProviderRow}>
                        <img src={PencilIcon} alt="제공처" style={{width:15, height:15, marginRight:4, verticalAlign:'middle'}} />
                        <span>{item.provider}</span>
                      </div>
                      <div className={styles.resultSourceLinkRow}>
                        <img src={CursorIcon} alt="클립" style={{width:15, height:15, marginRight:3, verticalAlign:'middle'}} />
                        <span className={styles.resultSourceRealLink}>{item.link ? item.link : "-"}</span>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      )}

      {/* 중앙 내용 (검색 결과 있을 때는 숨김) */}
      {!searchResult && (
        <div className={styles.contentsWrap}>
          {/* 인기질문 */}
          <div className={styles.section}>
            <div className={styles.sectionTitle}>
              <img src={LightbulbIcon} alt="" className={styles.titleIcon} />
              인기 질문
            </div>
            <div className={styles.grid}>
              {[
                { tag: "민원", text: "서산시청 민원 어떻게 넣어요?" },
                { tag: "민원", text: "서산시청 민원 어떻게 넣어요?" },
                { tag: "행사", text: "오늘 서산에 열리는 행사 뭐 있어?" },
                { tag: "행사", text: "오늘 서산에 열리는 행사 뭐 있어?" },
              ].map((q, i) => (
                <div key={i} className={styles.card}>
                  <div className={styles.cardTop}>
                    <span className={styles.tag}>{q.tag}</span>
                    <img src={ChatCircleDots} alt="" className={styles.cardIcon} />
                  </div>
                  <div className={styles.cardText}>{q.text}</div>
                </div>
              ))}
            </div>
          </div>
          {/* 인기카테고리 */}
          <div className={styles.section}>
            <div className={styles.sectionTitle}>
              <img src={LightningIcon} alt="" className={styles.titleIcon} />
              인기 카테고리
            </div>
            <div className={styles.gridCat}>
              <div className={styles.catCard}>
                <div>
                  <div className={styles.catTitle}>교통</div>
                  <div className={styles.catDesc}>
                    복잡한 서산시의 교통 노선,<br />바로 알아보세요
                  </div>
                </div>
                <img src={BusIcon} alt="교통" className={styles.catImg} />
                <img src={BlackCircle} alt="arrow" className={styles.arrowIcon} />
              </div>
              <div className={styles.catCard}>
                <div>
                  <div className={styles.catTitle}>복지</div>
                  <div className={styles.catDesc}>
                    복지혜택, 찾기 힘드신가요?<br />통합 정보를 확인하세요
                  </div>
                </div>
                <img src={HealthIcon} alt="복지" className={styles.catImg} />
                <img src={BlackCircle} alt="arrow" className={styles.arrowIcon} />
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
